-- Queer Atlas: Providence, Sacramento, Richmond, Dusseldorf and Cordoba.
-- Researched 2026-08-27. Directly uses only production-approved place types.
-- Idempotent: existing records are updated by city/name and missing records inserted.

begin;

alter table if exists public.places add column if not exists venue_intel jsonb not null default '{}'::jsonb;
alter table if exists public.events add column if not exists event_intel jsonb not null default '{}'::jsonb;
alter table if exists public.services add column if not exists service_intel jsonb not null default '{}'::jsonb;

do $qa_require_qari$
declare k text;
begin
  foreach k in array array['country:united-states','country:germany','country:argentina'] loop
    if not exists(select 1 from public.qa_qari_profiles where destination_key=k and scope_type='country' and is_published=true) then
      raise exception 'Published QARI profile % is required before this city batch can run.', k;
    end if;
  end loop;
end;
$qa_require_qari$;

with src as (
 select * from jsonb_to_recordset($qa_cities$
[
 {"slug":"providence","name":"Providence","title":"Queer Providence","country":"United States","country_code":"US","latitude":41.8240,"longitude":-71.4128,"timezone":"America/New_York","vibe":"compact, artistic and late-night social","local_mood":"Providence combines a walkable downtown gay-bar cluster with drag, leather, dance and neighbourhood-bar traditions, backed by major Pride visibility and strong health and youth organisations.","queer_status":"Six dedicated nightlife venues remain active, including one of the country's oldest continuously operating gay bars; the wider city is notably queer-integrated.","crowd_profile":"Gay men, lesbians, trans and non-binary people, drag audiences, leather communities, college students, artists and New England weekend visitors move between distinct but nearby rooms.","introduction":"Providence's compact circuit has unusual range for a small capital. Dark Lady and Alleycat form a paired drag-and-bar anchor, EGO supplies a larger dance floor, Stable and Mirabar work for neighbourhood socialising, and Providence Eagle serves leather and fetish communities. Rhode Island Pride's illuminated night parade gives the city a distinctive annual signature.","guide_items":[{"title":"About","text":"The scene is small enough to navigate easily but specialised enough that programme, age policy and audience matter."},{"title":"Districts","text":"Snow Street, Washington Street and Richmond Street form the downtown core; Mirabar sits a short trip south on Elbow Street."},{"title":"Safety","text":"Use normal late-night drink and transport awareness, check 18+/21+ rules, and respect consent and photography policies."},{"title":"Nightlife","text":"Choose by format: drag at Dark Lady, conversation at Alleycat or Stable, dance at EGO, history at Mirabar and leather at Eagle."},{"title":"Cost","text":"Covers vary by event; Pride and university weekends can raise downtown room prices."}],"guide_sources":[{"label":"GoProvidence LGBTQ guide","url":"https://www.goprovidence.com/lgbtq/"},{"label":"Rhode Island Pride","url":"https://prideri.org/"}],"safety_context":"Providence is broadly welcoming but venue-specific entry rules and crowded late-night streets still require planning. Verify official calendars and arrange a safe ride after closing.","qari_key":"country:united-states"},
 {"slug":"sacramento","name":"Sacramento","title":"Queer Sacramento","country":"United States","country_code":"US","latitude":38.5816,"longitude":-121.4944,"timezone":"America/Los_Angeles","vibe":"sunny, civic and deeply rooted","local_mood":"Lavender Heights concentrates a durable mix of large dance clubs, neighbourhood bars, queer-owned food and leather culture within Midtown, while community organisations broaden the scene beyond nightlife.","queer_status":"Seven current nightlife venues are documented by the destination authority, supported by a major LGBTQ community centre and longstanding Pride infrastructure.","crowd_profile":"Queer state workers, students, drag fans, Latino audiences, leather and bear communities, sports-watchers, couples and visitors from across Northern California find different rooms.","introduction":"Sacramento has one of California's clearest permanent queer districts. Faces and Badlands deliver multi-room dancing, The Depot and Mercantile offer classic bar culture, Roscoe's joins food with drag, Bear Dive supplies patio and tavern energy, and The Bolt remains the dedicated leather-cowboy-bear bar outside Midtown.","guide_items":[{"title":"About","text":"Lavender Heights is a real queer business cluster, not merely an occasional event district."},{"title":"Districts","text":"Most venues sit around K and 20th Streets in Midtown; The Bolt is north of the central grid and needs transport."},{"title":"Safety","text":"Plan for summer heat, hydration, ID checks and safe transport after 02:00 closing."},{"title":"Nightlife","text":"Start with food or a neighbourhood bar, then select Faces or Badlands by that night's programme."},{"title":"Cost","text":"Covers and VIP areas vary; central hotel demand rises around Pride, conventions and major arena dates."}],"guide_sources":[{"label":"Visit Sacramento LGBTQ guide","url":"https://www.visitsacramento.com/plan/lgbtq/"},{"label":"Visit Sacramento gay bars","url":"https://www.visitsacramento.com/plan/lgbtq/gay-bars/"},{"label":"Sacramento LGBT Community Center","url":"https://saccenter.org/"}],"safety_context":"Sacramento's core queer circuit is established and walkable, while The Bolt is separate. Carry valid ID, manage heat and use current first-party schedules.","qari_key":"country:united-states"},
 {"slug":"richmond","name":"Richmond","title":"Queer Richmond","country":"United States","country_code":"US","latitude":37.5407,"longitude":-77.4360,"timezone":"America/New_York","vibe":"historic, independent and creatively outspoken","local_mood":"Richmond's queer life is distributed across Carytown, downtown, the Arts District and Northside, mixing rare legacy bars with drag brunch, theatre, galleries, thrift and queer-owned dining.","queer_status":"Babe's, Godfrey's and Barcode provide permanent nightlife anchors while Diversity Richmond, Virginia Pride and Richmond Triangle Players create unusually visible cultural infrastructure.","crowd_profile":"Lesbians, trans and non-binary communities, gay men, drag audiences, theatre-goers, artists, students, Black and Latinx queer communities and allies overlap across neighbourhoods.","introduction":"Richmond rewards a broader route than a single bar crawl. Babe's of Carytown is a nationally significant lesbian-focused bar, Godfrey's is the drag-brunch institution, Barcode remains a relaxed downtown gay bar, Richmond Triangle Players is dedicated LGBTQ theatre, and Diversity Richmond's Iridian Gallery connects art to community funding. Papi's is excluded pending verified stable reopening after its long closure and permit process.","guide_items":[{"title":"About","text":"The city's strongest queer identity comes from independent businesses and nonprofit cultural infrastructure spread across several districts."},{"title":"Districts","text":"Carytown has Babe's; downtown has Godfrey's and Barcode; Northside holds Diversity Richmond and the Triangle Players."},{"title":"Safety","text":"Distances are larger than the map suggests; arrange transport and check venue-specific entry and accessibility."},{"title":"Nightlife","text":"Book Godfrey's brunch, check Babe's programme, and treat theatre or gallery nights as equal parts of the scene."},{"title":"Cost","text":"Brunch and theatre require advance booking; Pride and university events lift central accommodation demand."}],"guide_sources":[{"label":"Visit Richmond LGBTQ itinerary","url":"https://www.visitrichmondva.com/plan/itinerary-ideas/lgbtq/"},{"label":"OutRVA","url":"https://www.visitrichmondva.com/rrt-foundation/outrva/"},{"label":"Diversity Richmond","url":"https://www.diversityrichmond.org/"}],"safety_context":"Richmond is visibly queer-friendly but geographically spread. Verify schedules, do not rely on stale Papi's listings, and plan transport between districts.","qari_key":"country:united-states"},
 {"slug":"dusseldorf","name":"Düsseldorf","title":"Queer Düsseldorf","country":"Germany","country_code":"DE","latitude":51.2277,"longitude":6.7735,"timezone":"Europe/Berlin","vibe":"polished, carnival-minded and compact","local_mood":"Düsseldorf's small but resilient queer circuit stretches between Hauptbahnhof and Altstadt, combining traditional pubs, mixed lounges, gay bars and event-led clubs with strong Carnival and CSD culture.","queer_status":"The scene is smaller than Cologne's but includes several permanent bars and clubs; Phoenix Sauna is excluded because it closed in 2024.","crowd_profile":"Gay men, lesbians, trans and non-binary people, Carnival groups, after-work regulars, students, visitors and mixed local audiences meet in rooms with sharply different traditions.","introduction":"Düsseldorf is best read as two clusters. Around the station, K1, Comeback, Queenz, Bar Lola, Studio 1 and AromA create a late bar circuit; in Altstadt, Nähkörbchen preserves queer pub and Carnival history. Event calendars matter, and travellers should not follow old guides to the closed Phoenix Sauna.","guide_items":[{"title":"About","text":"The city's queer offer is intimate and programme-led, with CSD, Pink Monday and Carnival expanding its public scale."},{"title":"Districts","text":"The main bar cluster lies south and east of the centre near Hauptbahnhof; Nähkörbchen and Ludwigs sit in Altstadt."},{"title":"Safety","text":"Normal central-station and late-night precautions apply; indoor smoking occurs in some bars."},{"title":"Nightlife","text":"Begin at AromA or Lola, then choose K1 or Queenz; use official social feeds for current party nights."},{"title":"Cost","text":"Most bars are moderate, while trade fairs can make hotel prices exceptionally high."}],"guide_sources":[{"label":"Visit Düsseldorf LGBTQ","url":"https://www.visitduesseldorf.de/en/dus/lgbtq"},{"label":"City of Düsseldorf scene guide","url":"https://www.duesseldorf.de/int/tourism/discover/gaylesbian"},{"label":"Düsseldorf Queer","url":"https://www.duesseldorf-queer.de/"}],"safety_context":"Düsseldorf is open and well connected, but station-area awareness, smoke exposure and fast-changing club programming matter. Phoenix Sauna is closed and intentionally omitted.","qari_key":"country:germany"},
 {"slug":"cordoba","name":"Córdoba","title":"Queer Córdoba","country":"Argentina","country_code":"AR","latitude":-31.4201,"longitude":-64.1888,"timezone":"America/Argentina/Cordoba","vibe":"late, youthful and defiantly diverse","local_mood":"Córdoba's LGBTQ+ nightlife is dispersed across Centro, Nueva Córdoba and Güemes, with major discos, mixed bars, two saunas, an adult cinema and dedicated cruising spaces operating on genuinely late Argentine hours.","queer_status":"A current 2026 local specialist inventory documents a broad permanent scene, while city diversity programmes and an annual Pride march provide civic visibility.","crowd_profile":"Gay men, lesbians, trans communities, university students, drag audiences, artists, leather and cruising crowds, locals from across the province and domestic visitors participate in different spaces.","introduction":"Córdoba offers more venue variety than its fragmented map first suggests. Zen and Europa anchor dancing; Club Paraguay hosts recurring queer-friendly Limbo Pop; Tom Bar and Housing serve more adult and cruising-focused audiences; X Bar and Solutto are social alternatives; Clubb 466 and H. Edon provide sauna facilities; and Tao Sex retains the adult-cinema format. Each needs its own expectations around arrival time, privacy and payment.","guide_items":[{"title":"About","text":"The scene is not confined to one gay village and becomes much busier well after midnight."},{"title":"Districts","text":"Centro holds several adult venues; Nueva Córdoba and Güemes concentrate students, discos and mixed bars."},{"title":"Safety","text":"Use registered transport late at night, protect valuables and confirm cash/card policies and consent rules."},{"title":"Nightlife","text":"Do not arrive at a disco exactly at midnight expecting a full room; Córdoba's peak often comes after 01:30."},{"title":"Cost","text":"Inflation changes prices quickly, so verify covers and accepted payment methods on the day."}],"guide_sources":[{"label":"Córdoba Gay current venue guide","url":"https://cordobagay.com/lugares-gay-cordoba/"},{"label":"Municipality diversity programme","url":"https://cordoba.gob.ar/el-dia-internacional-del-orgullo-lgbtiqnb-se-celebra-con-la-primera-edicion-de-un-paseo-feria/"}],"safety_context":"Córdoba has active queer infrastructure but late operating hours and dispersed districts make transport planning important. Verify prices, payment and event schedules immediately before visiting.","qari_key":"country:argentina"}
]
$qa_cities$) c(slug text,name text,title text,country text,country_code text,latitude double precision,longitude double precision,timezone text,vibe text,local_mood text,queer_status text,crowd_profile text,introduction text,guide_items jsonb,guide_sources jsonb,safety_context text,qari_key text)
)
insert into public.qa_cities(slug,name,title,country,country_code,latitude,longitude,map_confirmed,timezone,vibe,local_mood,queer_status,crowd_profile,introduction,guide_items,guide_sources,guide_checked_at,safety_context,qari_destination_key,qari_score,qari_summary,qari_confidence,status,updated_at)
select c.slug,c.name,c.title,c.country,c.country_code,c.latitude,c.longitude,true,c.timezone,c.vibe,c.local_mood,c.queer_status,c.crowd_profile,c.introduction,c.guide_items,c.guide_sources,date '2026-08-27',c.safety_context,q.destination_key,q.qari_score,q.summary,q.confidence,'published',timezone('utc',now())
from src c cross join lateral(select destination_key,qari_score,summary,confidence from public.qa_qari_profiles where destination_key=c.qari_key and scope_type='country' and is_published=true order by reviewed_at desc nulls last limit 1) q
on conflict(slug) do update set name=excluded.name,title=excluded.title,country=excluded.country,country_code=excluded.country_code,latitude=excluded.latitude,longitude=excluded.longitude,map_confirmed=true,timezone=excluded.timezone,vibe=excluded.vibe,local_mood=excluded.local_mood,queer_status=excluded.queer_status,crowd_profile=excluded.crowd_profile,introduction=excluded.introduction,guide_items=excluded.guide_items,guide_sources=excluded.guide_sources,guide_checked_at=excluded.guide_checked_at,safety_context=excluded.safety_context,qari_destination_key=excluded.qari_destination_key,qari_score=excluded.qari_score,qari_summary=excluded.qari_summary,qari_confidence=excluded.qari_confidence,status='published',updated_at=excluded.updated_at;

with raw_places as (
 select * from jsonb_to_recordset($qa_places$
[
 {"name":"The Dark Lady","city":"providence","type":"club","description":"Downtown LGBTQ+ nightclub known for drag shows, dance events and large Pride-week crowds, operating beside its sister bar Alleycat.","hours":"Event-led evenings; verify current doors and age policy.","link":"https://www.darkladypvd.com/","location":"19 Snow Street, Providence, RI 02903, USA","lat":41.82339,"lng":-71.41488,"vibe":"high-energy drag and dance institution","q":"Popular shows and Pride dates queue early; entry policy changes by programme.","best":"Choose a named drag or DJ event rather than arriving without checking the calendar.","crowd":"Drag audiences, gay men, queer students, trans and non-binary guests and allies.","dress":"Expressive clubwear; event themes may add requirements.","staff":"Longstanding dedicated LGBTQ+ operator and Rhode Island Pride supporter.","sources":["https://www.goprovidence.com/lgbtq/","https://www.darkladypvd.com/"]},
 {"name":"The Alleycat","city":"providence","type":"bar","description":"Compact gay bar paired with The Dark Lady, offering a darker wood-lined room, cocktails, trivia and smaller-scale drag programming.","hours":"Evenings; verify daily hours and programme.","link":"https://www.alleycatpvd.com/","location":"17 Snow Street, Providence, RI 02903, USA","lat":41.82331,"lng":-71.41484,"vibe":"intimate downtown gay bar with conversation and event nights","q":"The narrow room fills quickly when Dark Lady events release.","best":"Early evening for conversation; later for trivia or hosted programmes.","crowd":"Mixed-age LGBTQ+ locals, couples, regulars and downtown visitors.","dress":"Casual bar clothing.","staff":"Explicitly presented as a gay bar by the official destination guide.","sources":["https://www.goprovidence.com/lgbtq/"]},
 {"name":"EGO Providence","city":"providence","type":"club","description":"Purpose-built LGBTQIA+ dance club with DJs, performers and late weekend hours in the Jewelry District.","hours":"Thursday and Sunday 22:00-01:00; Friday-Saturday 22:00-03:00; special events vary.","link":"https://egopvd.com/","location":"73 Richmond Street, Providence, RI 02903, USA","lat":41.81867,"lng":-71.40875,"vibe":"large late dance floor with diverse queer party energy","q":"Final-entry cutoffs precede closing and popular nights build a door line.","best":"Arrive before midnight and verify whether the event is 18+ or 21+.","crowd":"Young adult LGBTQIA+ dancers, students, drag fans and visiting groups.","dress":"Clubwear with theme-specific guidance.","staff":"The operator explicitly identifies the club as LGBTQIA+.","sources":["https://egopvd.com/","https://www.goprovidence.com/lgbtq/"]},
 {"name":"The Stable","city":"providence","type":"bar","description":"Friendly downtown gay bar known for cocktails, a social patio feel and weekly Sangria Sundays with guest bartenders.","hours":"Daily/evening schedule varies; verify official channels.","link":"https://www.stableprovidence.com/","location":"125 Washington Street, Providence, RI 02903, USA","lat":41.82157,"lng":-71.41655,"vibe":"welcoming neighbourhood-style gay bar in the downtown core","q":"Sangria Sundays and Pride weekends are busiest.","best":"Early evening for meeting friends; Sunday for its signature social programme.","crowd":"Gay men, mixed LGBTQ+ regulars, couples and New England visitors.","dress":"Relaxed smart-casual.","staff":"Official tourism describes it as Providence's premier gay bar where everyone is welcome.","sources":["https://www.goprovidence.com/lgbtq/"]},
 {"name":"Mirabar","city":"providence","type":"bar","description":"Historic gay bar tracing its operation to 1947, now offering karaoke, drag, dance parties and a cosy lounge on Elbow Street.","hours":"Evenings and programmed nights; verify current schedule.","link":"https://www.mirabar.com/","location":"15 Elbow Street, Providence, RI 02903, USA","lat":41.81295,"lng":-71.42000,"vibe":"historic, unpretentious gay lounge with karaoke and regulars","q":"Special shows change the room from quiet lounge to packed party.","best":"Karaoke or a listed drag night for its community character.","crowd":"Multigenerational gay and LGBTQ+ locals, loyal regulars and history-minded visitors.","dress":"Come-as-you-are.","staff":"One of the oldest continuously operating gay bars in the United States.","sources":["https://www.goprovidence.com/lgbtq/","https://www.mirabar.com/"]},
 {"name":"Providence Eagle","city":"providence","type":"bar","description":"Downtown gay leather bar serving bear, leather, fetish and broader LGBTQ+ communities with themed nights.","hours":"Evenings; verify programme and entry rules.","link":"https://www.eagle-pvd.com/","location":"124 Snow Street, Providence, RI 02903, USA","lat":41.82248,"lng":-71.41518,"vibe":"leather-rooted gay bar with direct, adult social energy","q":"Theme nights may add cover, dress or capacity rules.","best":"Attend a programme matching your interests and read its consent guidance first.","crowd":"Gay men, bears, leather and fetish communities and respectful LGBTQ+ guests.","dress":"Leather, fetish or casual depending on event; check before arrival.","staff":"Self-identifies as a gay bar and maintains community-specific programming.","sources":["https://www.eagle-pvd.com/","https://www.goprovidence.com/lgbtq/"]},

 {"name":"Faces Nightclub","city":"sacramento","type":"club","description":"Landmark gay dance club operating since 1985 with multiple dance floors, bars, drag, karaoke and rotating theme nights in Lavender Heights.","hours":"Wednesday-Sunday late; verify current doors and age rules.","link":"https://www.faces.net/","location":"2000 K Street, Sacramento, CA 95811, USA","lat":38.57624,"lng":-121.47974,"vibe":"large multi-room Sacramento institution built for dancing","q":"Weekend and Pride lines can be substantial; separate rooms open by demand.","best":"Pick a listed drag, Latin or DJ programme and arrive before peak.","crowd":"Broad LGBTQ+ mix, students, drag fans, Latino audiences and allies.","dress":"Clubwear; themed events vary.","staff":"Operator describes serving Sacramento's gay community since 1985.","sources":["https://www.faces.net/","https://www.visitsacramento.com/plan/lgbtq/gay-bars/"]},
 {"name":"Badlands Sacramento","city":"sacramento","type":"club","description":"Three-level LGBTQ+ nightclub with dance floors, drag showcases, karaoke and theme nights at the heart of Lavender Heights.","hours":"Evenings; verify weekly programme.","link":"https://www.badlandssac.com/","location":"2003 K Street, Sacramento, CA 95811, USA","lat":38.57616,"lng":-121.47961,"vibe":"bright multi-floor queer club driven by drag and DJs","q":"Popular showcases create a cover and door queue.","best":"Use the official weekly flyers to select the desired crowd and music.","crowd":"LGBTQ+ dancers, drag audiences, young professionals and visiting groups.","dress":"Expressive nightlife clothing.","staff":"Official destination authority identifies it as an LGBTQ+ hotspot.","sources":["https://www.badlandssac.com/","https://www.visitsacramento.com/plan/lgbtq/gay-bars/"]},
 {"name":"Roscoe's Bar & Burgers","city":"sacramento","type":"restaurant","description":"LGBTQ+-owned Lavender Heights restaurant and bar pairing burgers and cocktails with drag brunches and upstairs entertainment.","hours":"Food and bar hours vary by day; reserve drag brunch.","link":"https://www.roscoes916.com/","location":"2007 K Street, Sacramento, CA 95811, USA","lat":38.57612,"lng":-121.47948,"vibe":"queer-owned food, cocktails and drag in an accessible social setting","q":"Drag brunch and upstairs events book faster than ordinary dining.","best":"Reserve brunch or arrive early for dinner before clubbing nearby.","crowd":"LGBTQ+ diners, drag fans, couples, groups and allies.","dress":"Casual dining by day; celebratory for shows.","staff":"Visit Sacramento explicitly identifies Roscoe's as LGBTQ+ owned.","sources":["https://www.roscoes916.com/","https://www.visitsacramento.com/plan/lgbtq/gay-bars/"]},
 {"name":"The Depot","city":"sacramento","type":"bar","description":"Long-running LGBTQ+ neighbourhood bar in Lavender Heights with pool, trivia, strong drinks and a loyal local crowd.","hours":"Daily/evening schedule varies; verify social channels.","link":"https://www.facebook.com/thedepotsacramento/","location":"2001 K Street, Sacramento, CA 95811, USA","lat":38.57620,"lng":-121.47966,"vibe":"relaxed classic queer bar suited to conversation and pool","q":"Trivia and Pride nights fill the compact room.","best":"Early evening or a low-key weekday for local atmosphere.","crowd":"Mixed-age LGBTQ+ regulars, friends and bar-circuit visitors.","dress":"Casual.","staff":"Official tourism lists it as a dedicated LGBTQ+ bar.","sources":["https://www.visitsacramento.com/plan/lgbtq/gay-bars/"]},
 {"name":"The Mercantile Saloon","city":"sacramento","type":"bar","description":"Classic Lavender Heights gay bar, widely called The Merc, known for an unpretentious patio and strong neighbourhood-bar identity.","hours":"Daily/evenings; verify current listing.","link":"https://www.facebook.com/mercantilesaloon/","location":"1928 L Street, Sacramento, CA 95811, USA","lat":38.57541,"lng":-121.48115,"vibe":"laid-back old-school gay bar and patio hangout","q":"The small bar becomes crowded on weekend circuit nights.","best":"Afternoon or early evening for conversation before the clubs.","crowd":"Gay men, longtime locals, mixed LGBTQ+ friends and visitors.","dress":"No-fuss casual.","staff":"Recognised by Visit Sacramento as a favourite LGBTQ+ community bar.","sources":["https://www.visitsacramento.com/plan/lgbtq/gay-bars/"]},
 {"name":"The Bolt","city":"sacramento","type":"bar","description":"Sacramento's dedicated gay leather-cowboy-bear bar, with daily afternoon-to-late service and no regular cover.","hours":"Daily 14:00-02:00; 21+ with valid ID.","link":"https://sacbolt.com/","location":"2560 Boxwood Street, Sacramento, CA 95815, USA","lat":38.61166,"lng":-121.43096,"vibe":"direct leather, cowboy and bear community bar outside Midtown","q":"Theme events can increase attendance but the operator states no cover.","best":"Afternoon for relaxed socialising; event nights for leather-community energy.","crowd":"Leather men, cowboys, bears, pups and respectful adult LGBTQ+ visitors.","dress":"Casual or leather/fetish according to event.","staff":"Operator explicitly welcomes trans guests and defines the gay leather-cowboy-bear focus.","sources":["https://sacbolt.com/","https://www.visitsacramento.com/plan/lgbtq/gay-bars/"]},
 {"name":"Bear Dive","city":"sacramento","type":"bar","description":"LGBTQ+ tavern with burgers, sports, patio, pool tables and jukebox, offering a casual alternative to Lavender Heights dance clubs.","hours":"Daily food/bar schedule varies; verify current channels.","link":"https://www.instagram.com/beardivesac/","location":"1330 H Street, Sacramento, CA 95814, USA","lat":38.58218,"lng":-121.48715,"vibe":"casual queer tavern for sports, patio and bar food","q":"Sports and event nights can fill patio tables.","best":"Happy hour or a game night for its social tavern character.","crowd":"Bears, LGBTQ+ locals, sports fans, friends and allies.","dress":"Tavern casual.","staff":"Visit Sacramento includes it in the current gay-bar guide as LGBTQ+ friendly.","sources":["https://www.visitsacramento.com/plan/lgbtq/gay-bars/"]},

 {"name":"Babe's of Carytown","city":"richmond","type":"bar","description":"Lesbian-focused bar founded in 1979 with food, dancing, live music, drag and a beach-volleyball court, one of the longest-standing lesbian bars in the United States.","hours":"Daily schedule and events vary; verify official social channel.","link":"https://www.facebook.com/BabesofCarytown/","location":"3166 West Cary Street, Richmond, VA 23221, USA","lat":37.55257,"lng":-77.48039,"vibe":"historic lesbian bar mixing neighbourhood food, dance and outdoor play","q":"Weekend shows and Pride events create waits; restaurant and club rhythms differ.","best":"Early for food, later for dancing or a listed performance.","crowd":"Lesbians, queer women, trans and non-binary guests, mixed LGBTQ+ locals and allies.","dress":"Casual; event nights become expressive.","staff":"Official tourism identifies its lesbian focus and exceptional longevity.","sources":["https://www.visitrichmondva.com/plan/itinerary-ideas/lgbtq/","https://www.diversityrichmond.org/virginia-pride"]},
 {"name":"Godfrey's","city":"richmond","type":"restaurant","description":"Long-running LGBTQ+ restaurant, bar and performance venue best known for ticketed drag brunch and evening drag programming downtown.","hours":"Brunch and nightlife are programme-led; reservations essential for shows.","link":"https://godfreysva.com/","location":"308 East Grace Street, Richmond, VA 23219, USA","lat":37.54189,"lng":-77.43972,"vibe":"high-camp drag institution pairing brunch, cocktails and nightlife","q":"Drag brunch commonly sells out and uses timed seating.","best":"Reserve the official brunch slot well ahead; check evening show format separately.","crowd":"LGBTQ+ locals, drag fans, celebration groups and allies.","dress":"Brunch festive or nightlife expressive.","staff":"Operating as an LGBTQ+ institution since the 1990s and promoted by official tourism.","sources":["https://godfreysva.com/","https://www.visitrichmondva.com/plan/itinerary-ideas/lgbtq/"]},
 {"name":"Barcode","city":"richmond","type":"bar","description":"Downtown gay bar and grill known for martinis, friendly conversation, music and a mixed-age local crowd.","hours":"Evenings; verify current daily schedule.","link":"https://www.facebook.com/BarcodeRVA/","location":"6 East Grace Street, Richmond, VA 23219, USA","lat":37.54356,"lng":-77.44267,"vibe":"relaxed downtown gay bar with food and martinis","q":"Peak weekend periods can crowd the compact bar.","best":"Early evening for food and conversation; later for livelier music.","crowd":"Gay men, mixed LGBTQ+ locals, downtown workers and visitors.","dress":"Casual to smart-casual.","staff":"Visit Richmond presents Barcode as an LGBTQ-owned favourite.","sources":["https://www.visitrichmondva.com/plan/itinerary-ideas/lgbtq/"]},
 {"name":"Thirsty's RVA","city":"richmond","type":"bar","description":"South Richmond LGBTQ+ neighbourhood bar with karaoke, drag, games and a loyal local audience outside the tourist centre.","hours":"Evenings; programme and closing vary.","link":"https://www.facebook.com/ThirstysRVA/","location":"3516 Forest Hill Avenue, Richmond, VA 23225, USA","lat":37.52065,"lng":-77.47030,"vibe":"unpretentious queer neighbourhood bar driven by karaoke and regulars","q":"Hosted karaoke and drag nights fill faster than ordinary evenings.","best":"Choose a listed show or karaoke night and arrange transport from downtown.","crowd":"Broad LGBTQ+ neighbourhood crowd, performers, regulars and friends.","dress":"Come-as-you-are.","staff":"Locally recognised dedicated LGBTQ+ venue; current schedule should be checked directly.","sources":["https://www.facebook.com/ThirstysRVA/","https://www.visitrichmondva.com/rrt-foundation/outrva/"]},
 {"name":"Richmond Triangle Players","city":"richmond","type":"gallery","description":"Mid-Atlantic LGBTQ+ theatre company presenting queer plays, musicals and community programming in its dedicated Robert B. Moss Theatre.","hours":"Performance and box-office schedule varies by production.","link":"https://rtriangle.org/","location":"1300 Altamont Avenue, Richmond, VA 23230, USA","lat":37.56878,"lng":-77.45773,"vibe":"dedicated queer theatre joining performance, history and community","q":"Small-house productions can sell out; accessibility seating needs advance contact.","best":"Book a production early and arrive for the published house-opening time.","crowd":"LGBTQ+ theatre audiences, artists, students, subscribers and allies.","dress":"Theatre casual.","staff":"The company explicitly centres LGBTQ+ stories and artists.","sources":["https://rtriangle.org/","https://www.visitrichmondva.com/plan/itinerary-ideas/lgbtq/"]},
