[
 {"name":"Rhode Island PrideFest 2026","city":"providence","description":"The fiftieth-anniversary PrideFest and Illuminated Night Parade filled downtown Providence with community organisations, performance, vendors and a distinctive evening parade.","link":"https://prideri.org/","date":"2026-06-20","start_date":"2026-06-20T12:00:00-04:00","end_date":"2026-06-20T23:59:00-04:00","location":"195 District Park and downtown Providence, Rhode Island","lat":41.81970,"lng":-71.40820,"vibe":"large New England Pride festival culminating in an illuminated night parade","q":"Parade viewing and downtown security create the main congestion.","best":"Arrive during daylight for resources, then secure a parade position before evening.","crowd":"LGBTQIA+ New Englanders, families, performers, nonprofits and allies.","dress":"Pride expression with heat, rain and long walking considered.","host":"Rhode Island Pride is the state's dedicated LGBTQIA+ Pride organisation.","sources":["https://www.goprovidence.com/lgbtq/pride/","https://prideri.org/"]},
